    G.add(box(L*0.003, H*0.22, W*0.36, S.glass, cx+L*0.1515, H*0.70, 0));
    G.add(box(L*0.26, H*0.22, W*0.003, S.glass, cx, H*0.70, -W*0.201)); G.add(box(L*0.26, H*0.22, W*0.003, S.glass, cx, H*0.70, W*0.201));
